	client, err := coreapi.New()
	if err != nil {
		return fmt.Errorf("connect to Entire control plane: %w", err)
	}

	// --- pick repos ---------------------------------------------------------
	avail, err := client.ListAvailableMirrors(ctx, coreapi.ListAvailableMirrorsParams{})
	if err != nil {
		return renderCoreError(err)
	}
