	// default region, pre-selected. Guards against the seam silently widening.
	regions, err := availableRegions(t.Context(), nil)
	require.NoError(t, err)
	require.Len(t, regions, 1)
	require.Equal(t, defaultClusterHost, regions[0].host)
	require.True(t, regions[0].isDefault)
}

