63	func clustersToRegions(clusters []coreapi.Cluster) []regionChoice {
64		regions := make([]regionChoice, 0, len(clusters))
65		for _, cl := range clusters {
66			host, herr := hostFromPublicURL(cl.PublicUrl)
67			if herr != nil {
