222	// back to a lone cluster or a lone default; anything ambiguous errors so the
223	// caller can tell the user to pass [cluster-host]. Pure, so the selection is
224	// unit-testable without a live core.
225	func pickDefaultRegionHost(regions []regionChoice, jurisdiction string) (string, error) {
