	case coreapi.MirrorStatusSuspended:
		res.status, res.err = mirrorStatusSuspended, err
	case coreapi.MirrorStatusFailed:
		res.status, res.err = mirrorStatusFailed, err
	case coreapi.MirrorStatusProcessing:
		nonTerminal()
	default:
		nonTerminal()
	}
